103 :         long    result = 0;
104 :         int     end = offset + length;
105 :         int     start = offset;
106 : 
107 :         if (length < 2){
108 :             throw new IllegalArgumentException("Length "+length+" must be at least 2");
109 :         }
110 : 
111 :         if (buffer[start] == 0) {
112 :             return 0L;
113 :         }
114 : 
115 :         // Skip leading spaces
116 :         while (start < end){
117 :             if (buffer[start] == ' '){
118 :                 start++;
119 :             } else {
120 :                 break;
121 :             }
122 :         }
123 : 
124 :         // Trim all trailing NULs and spaces.
125 :         // The ustar and POSIX tar specs require a trailing NUL or
126 :         // space but some implementations use the extra digit for big
127 :         // sizes/uids/gids ...
128 :         byte trailer = buffer[end - 1];
129 :         if (trailer == 0 || trailer == ' '){
130 :             end--;
131 :         } else {
132 :             throw new IllegalArgumentException(
133 :                     exceptionMessage(buffer, offset, length, end-1, trailer));
134 :         }
135 :         trailer = buffer[end - 1];
136 :         while (start < end - 1 && (trailer == 0 || trailer == ' ')) {
137 :             end--;
138 :             trailer = buffer[end - 1];
139 :         }
140 : 
141 :         for ( ;start < end; start++) {
142 :             final byte currentByte = buffer[start];
143 :             // CheckStyle:MagicNumber OFF
144 :             if (currentByte < '0' || currentByte > '7'){
145 :                 throw new IllegalArgumentException(
146 :                         exceptionMessage(buffer, offset, length, start, currentByte));
147 :             }
148 :             result = (result << 3) + (currentByte - '0'); // convert from ASCII
149 :             // CheckStyle:MagicNumber ON
150 :         }
151 : 
152 :         return result;
153 :     }"

