"185 :     private static long parseBinaryLong(final byte[] buffer, final int offset,
186 :                                         final int length,
187 :                                         final boolean negative) {
188 :         if (length >= 9) {
189 :             throw new IllegalArgumentException("At offset " + offset + ", "
190 :                                                + length + " byte binary number"
191 :                                                + " exceeds maximum signed long"
192 :                                                + " value");
193 :         }
194 :         long val = 0;
195 :         for (int i = 1; i < length; i++) {
196 :             val = (val << 8) + (buffer[offset + i] & 0xff);
197 :         }
198 :         if (negative) {
199 :             // 2's complement
200 :             val--;
201 :             val ^= (long) Math.pow(2, (length - 1) * 8) - 1;
202 :         }
203 :         return negative ? -val : val;
204 :     }"

"206 :     private static long parseBinaryBigInteger(final byte[] buffer,
207 :                                               final int offset,
208 :                                               final int length,
209 :                                               final boolean negative) {
210 :         byte[] remainder = new byte[length - 1];
211 :         System.arraycopy(buffer, offset + 1, remainder, 0, length - 1);
